"""Main CLI entry point."""

import typer

from cli.connectors import connectors_app
from cli.outcomes import outcomes_app
from cli.version import __version__

app = typer.Typer(
    name="agentic-odi-cli",
    help="Agentic ODI CLI - Tool for managing Jobs-to-be-Done (JTBD) and ODI workflows.",
)
app.add_typer(connectors_app, name="connectors")

app.add_typer(outcomes_app, name="outcomes", help="Manage Customer Outcomes")


def _version_callback(value: bool) -> None:
    if value:
        typer.echo(__version__)
        raise typer.Exit()


@app.callback()
def main(
    version: bool = typer.Option(
        False, "--version", callback=_version_callback, help="Show version"
    ),
) -> None:  # noqa: B008
    pass


@app.command()
def version_cmd() -> None:
    """Show CLI version."""
    typer.echo(__version__)


if __name__ == "__main__":
    app()

"""Backend abstraction for CLI."""

from __future__ import annotations

import asyncio
import json
import os
from abc import ABC, abstractmethod
from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

import typer
from core import (
    CustomerOutcomeNotFoundError,
    JobNotFoundError,
    ODIService,
    OutcomeNotFoundError,
    StepNotFoundError,
    ValueOutOfRangeError,
    build_repository,
    customer_outcome_not_found,
    job_not_found,
)
from pydantic import ValidationError

_VALUE_RANGE_ERROR = "Error: importance and satisfaction must be between 1.0 and 10.0"

_CUSTOMER_VALUE_FIELDS = (
    "direction",
    "unit_of_measure",
    "object_of_control",
    "contextual_clarifier",
    "statement",
    "importance",
    "satisfaction",
    "value_metrics",
)

_BUSINESS_VALUE_FIELDS = {
    "category": "category",
    "business_statement": "statement",
    "detail": "detail",
    "estimated_annual_value": "estimated_annual_value",
    "confidence": "confidence",
}


def _job_id_error(job_id: str) -> str:
    return f"Error: Job with ID {job_id} not found."


def _step_id_error(step_id: str) -> str:
    return f"Error: Step with ID {step_id} not found."


def _outcome_id_error(outcome_id: str) -> str:
    return f"Error: Outcome with ID {outcome_id} not found."


def _call_mcp(tool: str, args: dict, mcp_url: str) -> str:
    from fastmcp import Client

    async def _run() -> str:
        async with Client(mcp_url) as client:
            result = await client.call_tool(tool, args)
            return result.content[0].text  # type: ignore[index]

    try:
        return asyncio.run(_run())
    except Exception as exc:  # noqa: BLE001
        typer.echo(f"Error: could not reach MCP server at {mcp_url}: {exc}", err=True)
        raise typer.Exit(code=1) from exc


class Backend(ABC):
    @abstractmethod
    def call(self, tool_name: str, args: dict) -> str:
        raise NotImplementedError


class LocalBackend(Backend):
    def __init__(self, db_path: str | None = None) -> None:
        self.service = ODIService(build_repository(db_path))
        self._handlers: dict[str, Callable[[dict], str]] = {
            "add_job": self._add_job,
            "get_jobs": self._get_jobs,
            "get_job": self._get_job,
            "update_job": self._update_job,
            "delete_job": self._delete_job,
            "add_step": self._add_step,
            "get_job_map": self._get_job_map,
            "get_step": self._get_step,
            "update_step": self._update_step,
            "delete_step": self._delete_step,
            "add_outcome": self._add_outcome,
            "get_outcomes": self._get_outcomes,
            "get_outcome": self._get_outcome,
            "update_outcome": self._update_outcome,
            "delete_outcome": self._delete_outcome,
            "add_customer_outcome": self._add_customer_outcome,
            "get_customer_outcome": self._get_customer_outcome,
            "list_customer_outcomes": self._list_customer_outcomes,
            "update_customer_outcome": self._update_customer_outcome,
            "delete_customer_outcome": self._delete_customer_outcome,
            "compute_opportunity": self._compute_opportunity,
        }

    def call(self, tool_name: str, args: dict) -> str:
        handler = self._handlers.get(tool_name)
        if handler is None:
            raise NotImplementedError(f"Unknown tool: {tool_name}")
        return handler(args)

    def _add_job(self, args: dict) -> str:
        job = self.service.add_job(name=args["name"], description=args.get("description"))
        return f"Job created successfully: {job.model_dump_json()}"

    def _get_jobs(self, args: dict) -> str:
        return json.dumps([job.model_dump() for job in self.service.get_jobs()])

    def _get_job(self, args: dict) -> str:
        job_id = args["job_id"]
        job = self.service.get_job(job_id)
        if job is None:
            return _job_id_error(job_id)
        return job.model_dump_json()

    def _update_job(self, args: dict) -> str:
        updates = {key: args[key] for key in ("name", "description") if key in args}
        try:
            job = self.service.update_job(args["job_id"], updates)
        except JobNotFoundError:
            return job_not_found(args["job_id"])
        return f"Job updated successfully: {job.model_dump_json()}"

    def _delete_job(self, args: dict) -> str:
        job_id = args["job_id"]
        try:
            self.service.delete_job(job_id)
        except JobNotFoundError:
            return job_not_found(job_id)
        return f"Job deleted successfully: {job_id}"

    def _add_step(self, args: dict) -> str:
        try:
            step = self.service.add_step(
                job_id=args["job_id"], name=args["name"], order=args["order"]
            )
        except JobNotFoundError:
            return job_not_found(args["job_id"])
        return f"Step created successfully: {step.model_dump_json()}"

    def _get_job_map(self, args: dict) -> str:
        job_id = args["job_id"]
        if self.service.get_job(job_id) is None:
            return _job_id_error(job_id)
        steps = self.service.get_job_map(job_id)
        return json.dumps([step.model_dump() for step in steps])

    def _get_step(self, args: dict) -> str:
        step_id = args["step_id"]
        step = self.service.get_step(step_id)
        if step is None:
            return _step_id_error(step_id)
        return step.model_dump_json()

    def _update_step(self, args: dict) -> str:
        updates = {key: args[key] for key in ("name", "order") if key in args}
        try:
            step = self.service.update_step(args["step_id"], updates)
        except StepNotFoundError:
            return _step_id_error(args["step_id"])
        return f"Step updated successfully: {step.model_dump_json()}"

    def _delete_step(self, args: dict) -> str:
        step_id = args["step_id"]
        try:
            self.service.delete_step(step_id)
        except StepNotFoundError:
            return _step_id_error(step_id)
        return f"Step deleted successfully: {step_id}"

    def _add_outcome(self, args: dict) -> str:
        try:
            outcome = self.service.add_outcome(
                job_id=args["job_id"],
                statement=args["statement"],
                importance=args.get("importance"),
                satisfaction=args.get("satisfaction"),
                step_id=args.get("step_id"),
            )
        except JobNotFoundError:
            return _job_id_error(args["job_id"])
        except StepNotFoundError:
            return _step_id_error(args["step_id"])
        except ValueOutOfRangeError:
            return _VALUE_RANGE_ERROR
        return f"Outcome created successfully: {outcome.model_dump_json()}"

    def _get_outcomes(self, args: dict) -> str:
        job_id = args["job_id"]
        if self.service.get_job(job_id) is None:
            return _job_id_error(job_id)
        outcomes = self.service.get_outcomes(job_id=job_id, step_id=args.get("step_id"))
        return json.dumps([outcome.model_dump() for outcome in outcomes])

    def _get_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        outcome = self.service.get_outcome(outcome_id)
        if outcome is None:
            return _outcome_id_error(outcome_id)
        return outcome.model_dump_json()

    def _update_outcome(self, args: dict) -> str:
        updates = {
            key: args[key]
            for key in ("statement", "importance", "satisfaction", "step_id")
            if key in args
        }
        try:
            outcome = self.service.update_outcome(args["outcome_id"], updates)
        except OutcomeNotFoundError:
            return _outcome_id_error(args["outcome_id"])
        except ValueOutOfRangeError:
            return _VALUE_RANGE_ERROR
        return f"Outcome updated successfully: {outcome.model_dump_json()}"

    def _delete_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            self.service.delete_outcome(outcome_id)
        except OutcomeNotFoundError:
            return _outcome_id_error(outcome_id)
        return f"Outcome deleted successfully: {outcome_id}"

    def _add_customer_outcome(self, args: dict) -> str:
        try:
            outcome = self.service.add_customer_outcome(
                job_id=args["job_id"],
                customer_value=args["customer_value"],
                business_value=args["business_value"],
                step_id=args.get("step_id"),
            )
        except JobNotFoundError:
            return _job_id_error(args["job_id"])
        except StepNotFoundError:
            return _step_id_error(args["step_id"])
        except ValidationError as exc:
            return f"Error: {exc}"
        return f"Customer outcome created successfully: {outcome.model_dump_json()}"

    def _get_customer_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            outcome = self.service.get_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        return outcome.model_dump_json()

    def _list_customer_outcomes(self, args: dict) -> str:
        outcomes = self.service.list_customer_outcomes(args.get("job_id"))
        return json.dumps([outcome.model_dump() for outcome in outcomes])

    def _update_customer_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            existing = self.service.get_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        customer_value = existing.customer_value.model_dump()
        for field in _CUSTOMER_VALUE_FIELDS:
            if field in args:
                customer_value[field] = args[field]
        business_value = existing.business_value.model_dump()
        for arg_key, field in _BUSINESS_VALUE_FIELDS.items():
            if arg_key in args:
                business_value[field] = args[arg_key]
        updates: dict[str, Any] = {
            "customer_value": customer_value,
            "business_value": business_value,
        }
        if "step_id" in args:
            updates["step_id"] = args["step_id"]
        try:
            outcome = self.service.update_customer_outcome(outcome_id, updates)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        except ValidationError as exc:
            return f"Error: {exc}"
        return f"Customer outcome updated successfully: {outcome.model_dump_json()}"

    def _delete_customer_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            self.service.delete_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        return f"Customer outcome deleted successfully: {outcome_id}"

    def _compute_opportunity(self, args: dict) -> str:
        importance = args["importance"]
        satisfaction = args["satisfaction"]
        if not (1.0 <= importance <= 10.0) or not (1.0 <= satisfaction <= 10.0):
            return _VALUE_RANGE_ERROR
        score = self.service.compute_opportunity(importance, satisfaction)
        return f"Opportunity score: {score:.2f}"


class MCPBackend(Backend):
    def __init__(self, mcp_url: str) -> None:
        self.mcp_url = mcp_url

    def call(self, tool_name: str, args: dict) -> str:
        return _call_mcp(tool_name, args, self.mcp_url)


@dataclass
class BackendConfig:
    backend: str
    db_path: str | None = None
    mcp_url: str | None = None


def get_backend(
    backend: str | None = None, db_path: str | None = None, mcp_url: str | None = None
) -> Backend:
    if backend is None:
        backend = os.environ.get("AGENTIC_ODI_BACKEND", "local")
    if backend == "local":
        return LocalBackend(db_path=db_path)
    if backend == "mcp":
        return MCPBackend(
            mcp_url or os.environ.get("AGENTIC_ODI_MCP_URL", "http://localhost:8000/mcp")
        )
    raise ValueError(f"Unknown backend: {backend}")


def resolve_backend(config: BackendConfig) -> Backend:
    if config.backend == "mcp" and config.db_path:
        typer.echo("Warning: db_path is ignored when backend is 'mcp'", err=True)
    return get_backend(backend=config.backend, db_path=config.db_path, mcp_url=config.mcp_url)

"""Customer Outcomes CLI subcommands."""

from __future__ import annotations

import os
from enum import Enum
from typing import Any

import typer

from cli.backend import _call_mcp

MCP_URL_DEFAULT = os.getenv("AGENTIC_ODI_MCP_URL", "http://localhost:8000/mcp")

outcomes_app = typer.Typer(help="Manage Customer Outcome entities.")


class DirectionOption(str, Enum):
    MINIMIZE = "minimize"
    MAXIMIZE = "maximize"


class CategoryOption(str, Enum):
    REVENUE_GROWTH = "revenue_growth"
    COST_REDUCTION = "cost_reduction"
    RETENTION = "retention"
    RISK_MITIGATION = "risk_mitigation"
    OPERATIONAL_EFFICIENCY = "operational_efficiency"
    COMPLIANCE = "compliance"
    BRAND_REPUTATION = "brand_reputation"
    OTHER = "other"


@outcomes_app.command("add")
def add(
    job_id: str = typer.Option(..., help="Job ID the outcome belongs to"),
    direction: DirectionOption = typer.Option(..., help="minimize | maximize"),  # noqa: B008
    unit_of_measure: str = typer.Option(..., "--unit"),
    object_of_control: str = typer.Option(..., "--object"),
    statement: str = typer.Option(..., help="Full outcome statement"),
    importance: float = typer.Option(..., min=1.0, max=10.0),
    satisfaction: float = typer.Option(..., min=1.0, max=10.0),
    category: CategoryOption = typer.Option(..., help="Business impact category"),  # noqa: B008
    business_statement: str = typer.Option(..., help="Business value statement"),
    contextual_clarifier: str | None = typer.Option(default=None),
    step_id: str | None = typer.Option(default=None),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """Add a Customer Outcome with customer and business value."""
    customer_value = {
        "direction": direction.value,
        "unit_of_measure": unit_of_measure,
        "object_of_control": object_of_control,
        "statement": statement,
        "importance": importance,
        "satisfaction": satisfaction,
    }
    if contextual_clarifier:
        customer_value["contextual_clarifier"] = contextual_clarifier
    business_value = {
        "category": category.value,
        "statement": business_statement,
    }
    args: dict[str, Any] = {
        "job_id": job_id,
        "customer_value": customer_value,
        "business_value": business_value,
    }
    if step_id:
        args["step_id"] = step_id
    from cli.backend import get_backend

    typer.echo(get_backend("mcp", mcp_url=mcp_url).call("add_customer_outcome", args))


@outcomes_app.command("get")
def get(
    outcome_id: str = typer.Argument(...),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """Get a Customer Outcome by ID."""
    from cli.backend import get_backend

    typer.echo(
        get_backend("mcp", mcp_url=mcp_url).call("get_customer_outcome", {"outcome_id": outcome_id})
    )


@outcomes_app.command("list")
def list_outcomes(
    job_id: str | None = typer.Option(default=None, help="Filter by job ID"),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """List Customer Outcomes."""
    args: dict[str, Any] = {}
    if job_id:
        args["job_id"] = job_id
    from cli.backend import get_backend

    typer.echo(get_backend("mcp", mcp_url=mcp_url).call("list_customer_outcomes", args))


@outcomes_app.command("update")
def update(
    outcome_id: str = typer.Argument(...),
    importance: float | None = typer.Option(default=None, min=1.0, max=10.0),
    satisfaction: float | None = typer.Option(default=None, min=1.0, max=10.0),
    direction: DirectionOption | None = typer.Option(default=None),  # noqa: B008
    unit_of_measure: str | None = typer.Option(default=None, help="Unit of measure"),
    object_of_control: str | None = typer.Option(default=None, help="Object of control"),
    contextual_clarifier: str | None = typer.Option(default=None),
    statement: str | None = typer.Option(default=None),
    category: CategoryOption | None = typer.Option(default=None),  # noqa: B008
    business_statement: str | None = typer.Option(default=None),
    detail: str | None = typer.Option(default=None),
    estimated_annual_value: float | None = typer.Option(default=None),
    confidence: float | None = typer.Option(default=None),
    step_id: str | None = typer.Option(default=None),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """Update a Customer Outcome."""
    args: dict[str, Any] = {"outcome_id": outcome_id}
    if step_id is not None:
        args["step_id"] = step_id
    if importance is not None:
        args["importance"] = importance
    if satisfaction is not None:
        args["satisfaction"] = satisfaction
    if direction is not None:
        args["direction"] = direction.value
    if unit_of_measure is not None:
        args["unit_of_measure"] = unit_of_measure
    if object_of_control is not None:
        args["object_of_control"] = object_of_control
    if contextual_clarifier is not None:
        args["contextual_clarifier"] = contextual_clarifier
    if statement is not None:
        args["statement"] = statement
    if category is not None:
        args["category"] = category.value
    if business_statement is not None:
        args["business_statement"] = business_statement
    if detail is not None:
        args["detail"] = detail
    if estimated_annual_value is not None:
        args["estimated_annual_value"] = estimated_annual_value
    if confidence is not None:
        args["confidence"] = confidence
    from cli.backend import get_backend

    typer.echo(get_backend("mcp", mcp_url=mcp_url).call("update_customer_outcome", args))


@outcomes_app.command("delete")
def delete(
    outcome_id: str = typer.Argument(...),
    yes: bool = typer.Option(False, "--yes", "-y", help="Skip confirmation"),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """Delete a Customer Outcome."""
    if not yes:
        confirm = typer.confirm(f"Delete customer outcome {outcome_id}?")
        if not confirm:
            raise typer.Exit()
    from cli.backend import get_backend

    typer.echo(
        get_backend("mcp", mcp_url=mcp_url).call(
            "delete_customer_outcome", {"outcome_id": outcome_id}
        )
    )


@outcomes_app.command("score")
def score(
    importance: float = typer.Argument(..., min=1.0, max=10.0),
    satisfaction: float = typer.Argument(..., min=1.0, max=10.0),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """Compute ODI Opportunity Score."""
    typer.echo(
        _call_mcp(
            "compute_opportunity",
            {"importance": importance, "satisfaction": satisfaction},
            mcp_url,
        )
    )

